import assert from 'node:assert/strict';
import { generateText, streamText } from 'ai';
import { createXai } from '@ai-sdk/xai';
if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
// Twenty's xAI provider (sdk-provider-factory.service.ts: createXai({ apiKey }).responses(modelId)), its key XAI_API_KEY
const xai = createXai({ apiKey: process.env.XAI_API_KEY });
const model = xai.responses('grok-4.7');
// the twin runs no model: an unscripted turn is its labelled stub, asserted as a stub
const stub = (said) => '[twin-stub:grok-4.7] This is a deterministic stub from the xAI API twin (no model runs). Your last message: ' + said;
const asked = await generateText({ model, prompt: 'Where does the Orbit deal stand?' });
assert.equal(asked.text, stub('Where does the Orbit deal stand?'));
assert.equal(asked.finishReason, 'stop');
assert.equal(asked.response.modelId, 'grok-4.7');
assert.ok(asked.response.id, 'the response names its id');
assert.ok(asked.usage.inputTokens > 0 && asked.usage.outputTokens > 0, 'the response counts its tokens: ' + JSON.stringify(asked.usage));
assert.ok(asked.reasoningText, 'grok-4.7 answers with its reasoning item');
const followed = streamText({ model, messages: [
  { role: 'user', content: 'Where does the Orbit deal stand?' },
  { role: 'assistant', content: asked.text },
  { role: 'user', content: 'What should Mira prepare for the pricing call?' },
] });
let streamed = '';
for await (const part of followed.textStream) streamed += part;
assert.equal(streamed, stub('What should Mira prepare for the pricing call?'));
assert.equal(await followed.finishReason, 'stop');
console.log(JSON.stringify({ model: asked.response.modelId, asked: asked.text, streamed, usage: asked.usage }));
